import {
  petSoundCue,
  petVoiceClip,
  type PetReaction,
  type PetSpecies,
  type PetStage,
} from "@zoption/shared";

import { soundEffectsPreference } from "./browserPreferences";

// The pet voices in public/pet/sounds, generated by scripts/generate-pet-sounds.mjs.

const players = new Map<string, HTMLAudioElement>();

function playerFor(name: string): HTMLAudioElement {
  let player = players.get(name);
  if (!player) {
    player = new Audio(`/pet/sounds/${name}.wav`);
    player.preload = "auto";
    // Let the playback rate move the pitch, so a baby sounds higher than a legend.
    player.preservesPitch = false;
    players.set(name, player);
  }
  return player;
}

function playClip(name: string, rate: number, volume: number): void {
  const player = playerFor(name);
  player.playbackRate = rate;
  player.volume = volume;
  // Restart, so a quick second click is heard rather than ignored.
  player.currentTime = 0;
  player.play().catch(() => {
    // Sound is decoration; a blocked or missing clip stays silent.
  });
}

/** Starts loading one pet's voices and the sparkle ahead of the first click. */
export function warmUpPetVoices(species: PetSpecies): void {
  if (typeof Audio === "undefined") return;
  for (const name of [petVoiceClip(species, "happy"), petVoiceClip(species, "sad"), "sparkle"]) {
    playerFor(name);
  }
}

/**
 * Plays the pet's own voice for a reaction, pitched by stage, plus the sparkle on a dance. Only
 * while this browser's Sound effects switch is on. Fire and forget.
 */
export function playPetReaction(
  species: PetSpecies,
  stage: Exclude<PetStage, "egg">,
  reaction: PetReaction,
): void {
  if (!soundEffectsPreference.get() || typeof Audio === "undefined") return;
  const cue = petSoundCue(stage, reaction);
  playClip(petVoiceClip(species, cue.voice), cue.rate, cue.volume);
  if (cue.sparkle) playClip("sparkle", 1, 1);
}
